  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "Chat med en modell du velger; {mnemo} leser, skriver, tagger, lenker, flytter og rydder notater med Memoras egne verktøy. Den kan ikke surfe på nettet, kjøre kommandoer, slette for godt eller endre serveren. Nøkler er forseglet på denne serveren og sendes aldri til nettleseren.",
