  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude og ChatGPT logger inn med Memora-kontoen din. Ingenting å kopiere.",
  "Claude models": "Claude-modeller",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude logger inn via OAuth, så ingen nøkkel limes inn: den får sin egen nøkkel når du trykker Tillat. Uten innlogging kobler du den til som <b>Annen app</b> og sender headeren <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor og flere",
