  "Deleted chats and their messages are gone for good. Your notes are not touched, and a chat that is answering right now is left alone.": "Slettede chatter og meldingene deres er borte for godt. Notatene dine berøres ikke, og en chat som svarer akkurat nå, lar vi være.",
