  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "Dra et kort til en annen mapperamme for å flytte notatet på disken. Dra en ramme i navnet for å ordne brettet; slipp den på en annen ramme for å flytte hele mappen dit. Dobbeltklikk en tittel for å gi nytt navn. På berøring: dra for å panorere, knip for å zoome, trykk og hold et kort for å flytte det, trykk for forhåndsvisning.",
  "Drag a note here to pin it": "Dra et notat hit for å feste det",
  "Drag notes or folders here to pin them": "Dra notater eller mapper hit for å feste dem",
  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "Dra notater eller mapper til en mappe for å flytte dem, til Festet for å feste dem.",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "Dra notater · dobbeltklikk for å feste · / søk · #tag finner tagger · F tilpass · 1 2 3 oppsett",
  "Drag to move the folder frame; double-click to rename": "Dra for å flytte mapperammen; dobbeltklikk for å gi nytt navn",
  "Drag to move the lane. Double click the name to rename it.": "Dra for å flytte kolonnen. Dobbeltklikk på navnet for å gi det nytt navn.",
  "Drag to resize · double-click to reset": "Dra for å endre størrelse · dobbeltklikk for å nullstille",
  "Drag to turn · scroll to zoom · click a point to open its note": "Dra for å rotere · rull for å zoome · klikk på et punkt for å åpne notatet",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "Dra for å rotere · rull for å zoome · klikk på et punkt for å åpne notatet · / for å søke · #tag finner tagger",
