  "Dyslexic": "Dysleksi",
  "Each AI app connects over MCP with its own key and permissions.": "Hver AI-app kobler til over MCP med sin egen nøkkel og egne tillatelser.",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "Hver AI-app du kobler til, er en agent med sin egen nøkkel, så du ser hva hver enkelt gjør og kan slå én av for seg.",
  "Each agent": "Hver agent",
  "Each agent belongs to one app. For another app or device, make a new agent.": "Hver agent hører til én app. For en annen app eller enhet, lag en ny agent.",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "Hver agent hører til én app. For å bruke Memora i en annen app, opprett en egen agent for den.",
  "Each app gets its own key": "Hver app får sin egen nøkkel",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "Hver har en kort ID som aldri endres, så navn kan byttes fritt. Mnemo setter dem opp, endrer instruksene eller modellen deres, sender meldinger, venter på, stopper, avslutter og fjerner dem, én om gangen eller alle samtidig, og kan la dem jobbe i bakgrunnen. Hvert kort viser Instruks, Aktivitet og Svar.",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "Hver type måles mot sitt eget rom: grensen hvis den er satt, ellers det den bruker pluss ledig diskplass{disk}. Tom grense: ingen.",
  "Each one gets its own key from Memora.": "Hver av dem får sin egen nøkkel fra Memora.",
