  "Entries": "Oppføringer",
  "Error": "Feil",
  "Error 404": "Feil 404",
  "Even in daily use, a browser signs in again after this long. It cannot be shorter than the inactivity time.": "Selv ved daglig bruk logger en nettleser inn på nytt etter så lang tid. Den kan ikke være kortere enn inaktivitetstiden.",
  "Every AI loses {n} tool at once. Asks first.": "Alle AI-er mister {n} verktøy samtidig. Spør først.",
  "Every AI loses {n} tools at once. Asks first.": "Alle AI-er mister {n} verktøy samtidig. Spør først.",
  "Every Kanban board in your notes": "Hver Kanban-tavle i notatene dine",
  "Every action, newest first": "Alle handlinger, nyeste først",
  "Every action, newest first, with search and filters.": "Alle handlinger, nyeste først, med søk og filtre.",
  "Every address from one to another.": "Alle adresser fra én til en annen.",
  "Every address from the first to the last, joined by a dash.": "Alle adresser fra den første til den siste, forbundet med en bindestrek.",
  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "Hver agent starter vanligvis fra null. {bold} koble til hver agent én gang, så leser de alle det samme hvelvet og skriver tilbake til det, slik at det én lærer, kan de andre bruke.",
  "Every archived card is back on the board": "Alle arkiverte kort er tilbake på brettet",
  "Every board with its lanes and progress. New board sits wherever New note does: the sidebar, Overview, folders, menus, search and the B key.": "Hver tavle med kolonner og fremdrift. Ny tavle finnes overalt der Nytt notat gjør: i sidefeltet, Oversikt, mapper, menyer, søk og B-tasten.",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "Alle nettlesere og agenter kobles fra til noen starter Memora på nytt på den maskinen. Denne siden kan ikke starte den igjen.",
  "Every call shows up live in the brain and Activity": "Hvert kall vises live i hjernen og i Aktivitet",
  "Every change Mnemo makes shows in Activity and can be undone from History.": "Alle endringer Mnemo gjør, vises i Aktivitet og kan angres fra Historikk.",
  "Every change, by you or an app, shows in Activity and can be undone from History.": "Alle endringer, av deg eller en app, vises i Aktivitet og kan angres fra Historikk.",
  "Every chat is archived.": "Alle chatter er arkivert.",
  "Every chat with your notes agent": "Alle chatter med notatagenten din",
  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "Alle tilkoblede AI-er mister alle {n} verktøy samtidig og kan ikke lenger lese eller endre notatene dine før du slår verktøyene på igjen her.",
  "Every connected AI loses it at once. You can turn it back on any time.": "Alle tilkoblede AI-er mister det samtidig. Du kan slå det på igjen når som helst.",
  "Every connected AI loses them at once. You can turn them back on any time.": "Alle tilkoblede AI-er mister dem samtidig. Du kan slå dem på igjen når som helst.",
  "Every connected agent loses its memory until Memora runs again.": "Alle tilkoblede agenter mister minnet til Memora kjører igjen.",
  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "Alle enheter på et hjemme- eller kontornettverk, skrevet som adresse/størrelse: 192.168.1.0/24 dekker 192.168.1.0 til 192.168.1.255.",
  "Every device on a home or office network.": "Alle enheter på et hjemme- eller kontornettverk.",
  "Every image in the notes folder and where it is shown, and the pictures kept for Mnemo chats.": "Alle bilder i notatmappen og hvor de vises, og bildene som er lagret for Mnemo-chatter.",
  "Every image is used in a note.": "Alle bilder brukes i et notat.",
  "Every note": "Alle notater",
  "Every note and link, in 3D, as a graph or on a board.": "Alle notater og lenker, i 3D, som graf eller på et brett.",
  "Every note and subfolder in \"{path}\" moves into {folder}; \"{name}\" is then removed. If a name is already taken there, a number is added to it.": "Alle notater og undermapper i «{path}» flyttes til {folder}; «{name}» fjernes deretter. Hvis et navn allerede er tatt der, legges det til et tall.",
  "Every note becomes a card here, inside a frame for its folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Hvert notat blir et kort her, inne i en ramme for mappen sin. Veiledningen viser hvordan du får en AI til å lagre kunnskapen sin her, eller hvordan du skriver et notat selv.",
  "Every note becomes a point of light here, grouped by folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Hvert notat blir et lyspunkt her, gruppert etter mappe. Veiledningen viser hvordan du får en AI til å lagre kunnskapen sin her, eller hvordan du skriver et notat selv.",
  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "Alle notater med taggen #{tag} ({notes}) får det nye navnet, også innebygde #tagger i teksten.",
  "Every note tagged {tags} gets one tag instead ({notes}). Inline #tags in the text change too. There is no one-step undo; each note keeps its history.": "Alle notater med taggene {tags} får én tagg i stedet ({notes}). Innebygde #tagger i teksten endres også. Det finnes ingen angring i ett trinn; hvert notat beholder historikken sin.",
  "Every read and write by an agent shows up live, so you always know who did what.": "Hver lesing og skriving fra en agent vises live, så du alltid vet hvem som gjorde hva.",
  "Every request that reaches this rule is {verb}.": "Alle forespørsler som treffer denne regelen, blir {verb}.",
  "Every request. Put it last, to catch whatever the rules above did not.": "Alle forespørsler. Sett den sist, for å fange det reglene over ikke traff.",
  "Every setting and where it lives.": "Alle innstillinger og hvor de finnes.",
  "Every shortcut in the web UI.": "Alle snarveier i nettgrensesnittet.",
