  "General": "Generelt",
  "Get a one-time code on the server": "Få en engangskode på serveren",
  "Get started": "Kom i gang",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "Bli kjent med meg gjennom notatene mine. Gå gjennom hvelvet mitt (nyere notater, dagbøker, prosjekter, alt om meg), og ta vare på det du lærer med remember_owner: hvem jeg er, hva jeg jobber med, hvordan jeg vil ha svar, hva jeg liker. Bare korte, varige ting, aldri hemmeligheter. Fortell meg deretter i noen linjer hva du tok vare på.",
  "Gets its own agent key: read and write nodes over MCP": "Får sin egen agentnøkkel: leser og skriver noder over MCP",
  "Getting started": "Kom i gang",
  "GitHub answered HTTP {code}": "GitHub svarte med HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Gi Claude, Cursor eller en annen MCP-app sin egen nøkkel, og la den lagre det den allerede vet om deg.",
  "Give a key read-only access, or let it write too.": "Gi en nøkkel skrivebeskyttet tilgang, eller la den skrive også.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "Gi hver app eller enhet sin egen agent. Aktivitet viser da nøyaktig hvem som gjorde hva, og du kan slå én av uten å røre de andre.",
