  "I find, read, write, tag, link and tidy your notes. No web, no shell: only your vault.": "Jeg finner, leser, skriver, tagger, lenker og rydder notatene dine. Ingen web, ingen shell: bare hvelvet ditt.",
  "Icon": "Ikon",
  "Icon {name}": "Ikon {name}",
  "Ideas grow when they connect. Link this note to {a} or read {b}.": "Ideer vokser når de kobles sammen. Lenk dette notatet til {a} eller les {b}.",
  "Identity": "Identitet",
  "Idle": "Inaktiv",
  "If it's been useful to you, a star on GitHub or telling a friend helps others find it. No worries if not.": "Hvis den har vært nyttig for deg, hjelper en stjerne på GitHub eller å fortelle det til en venn andre å finne den. Ingen fare hvis ikke.",
  "If you leave, they are kept on this device and offered again when you open the note.": "Hvis du forlater den, beholdes de på denne enheten og tilbys igjen når du åpner notatet.",
  "Image": "Bilde",
  "Image (or paste or drop one)": "Bilde (eller lim inn eller slipp ett)",
  "Image deleted": "Bildet er slettet",
  "Image line copied": "Bildelinjen er kopiert",
  "Image you attached": "Bilde du la ved",
  "Image {name}": "Bilde {name}",
  "Images": "Bilder",
  "Images can now be up to {n} MB": "Bilder kan nå være opptil {n} MB",
  "Images in this folder": "Bilder i denne mappen",
  "Images live beside the notes that show them. Choose how large one may be, and see what notes and images take.": "Bilder ligger ved siden av notatene som viser dem. Velg hvor store de kan være, og se hva notater og bilder tar.",
  "Import and export": "Import og eksport",
  "Imported": "Importert",
  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "I ChatGPT åpner du <b>Settings → Apps &amp; Connectors → Advanced settings</b> og slår på <b>Developer mode</b>. Velg deretter <b>Create</b>.",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "I Claude (web eller skrivebord) åpner du <b>Settings → Connectors</b> og velger <b>Add custom connector</b>.",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "I Claude Desktop åpner du <b>Settings → Developer → Edit Config</b>. I nyere versjoner velger du <b>Claude</b> i stedet.",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "I Windsurf åpner du <b>Settings → Cascade → MCP servers</b> og velger <b>View raw config</b>.",
  "In colour": "I farge",
  "In note text": "I notatteksten",
  "In notes": "I notater",
  "In search: actions only (new note, theme ...)": "I søk: bare handlinger (nytt notat, tema ...)",
