  "Installed": "Installert",
  "Installing, connecting agents, settings and reference.": "Installasjon, tilkobling av agenter, innstillinger og referanse.",
  "Instance not ready": "Instansen er ikke klar",
  "Instruction": "Instruks",
  "Instruction style": "Instruksjonsstil",
  "Instructions": "Instruksjoner",
  "Instructions from {mnemo}": "Instrukser fra {mnemo}",
  "Interface": "Grensesnitt",
  "Internet (tunnel)": "Internett (tunnel)",
  "Internet address (IP)": "Internettadresse (IP)",
  "It becomes your first rule.": "Den blir din første regel.",
  "It becomes {path}. Links to its notes keep working.": "Den blir {path}. Lenker til notatene dens fortsetter å virke.",
  "It can change notes, but nothing lets it connect.": "Den kan endre notater, men ingenting lar den koble til.",
  "It can search and read your notes, but not change them": "Den kan søke i og lese notatene dine, men ikke endre dem",
  "It can search, read and save your notes": "Den kan søke i, lese og lagre notatene dine",
  "It can {list}.": "Den kan {list}.",
  "It cannot do anything yet": "Den kan ikke gjøre noe ennå",
  "It has full control: it reads and changes notes, and can manage Memora and other agents": "Den har full kontroll: den leser og endrer notater, og kan administrere Memora og andre agenter",
  "It holds {n} note. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Den inneholder {n} notat. Neste steg er å velge hva som skjer med dem: flytt dem til en annen mappe, eller flytt dem til Papirkurven. Ingenting er endret ennå.",
  "It holds {n} notes. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Den inneholder {n} notater. Neste steg er å velge hva som skjer med dem: flytt dem til en annen mappe, eller flytt dem til Papirkurven. Ingenting er endret ennå.",
  "It is added at the end, as rule {n}, so it is checked last.": "Den legges til på slutten, som regel {n}, så den sjekkes sist.",
  "It is gone when you leave, pictures included. Changes to your notes still show in Activity and History.": "Det forsvinner når du går, bilder også. Endringer i notatene dine vises fortsatt i Aktivitet og Historikk.",
  "It is kept locked on the server. Enter your Memora password and the buttons below put it in for you.": "Den holdes låst på serveren. Skriv inn Memora-passordet ditt, så fyller knappene nedenfor den inn for deg.",
  "It is taking a while. Check the server, then reload this page.": "Det tar tid. Sjekk serveren og last denne siden på nytt.",
  "It leaves the Pinned list only; the folder itself stays where it is.": "Den forlater bare Festet-listen; selve mappen blir der den er.",
  "It leaves the Pinned list only; the note itself stays where it is.": "Den forlater bare Festet-listen; selve notatet blir der det er.",
  "It may have been renamed, moved or deleted. Deleted notes wait in the Trash.": "Det kan være gitt nytt navn, flyttet eller slettet. Slettede notater venter i Papirkurven.",
  "It moves; links to it are updated and pins follow.": "Den flyttes; lenker til den oppdateres og festinger følger med.",
  "It must sign in again and is told why": "Den må logge inn på nytt og får vite hvorfor",
  "It prints a one-time code. This page moves on by itself.": "Den skriver ut en engangskode. Denne siden går videre av seg selv.",
  "It reached Memora but did not finish. It often works on the next try.": "Den nådde Memora, men ble ikke ferdig. Det virker ofte ved neste forsøk.",
  "It reached Memora but did not finish: {error} It often works on the next try.": "Den nådde Memora, men ble ikke ferdig: {error} Det virker ofte ved neste forsøk.",
  "It shows up under this name in Activity, the brain and the graph. Name it after the device when you use {app} in more than one place, like \"{example}\".": "Den vises under dette navnet i Aktivitet, hjernen og grafen. Gi den navn etter enheten når du bruker {app} på mer enn ett sted, som «{example}».",
  "It was shown when it was made. Make a new key to see one again.": "Den ble vist da den ble laget. Lag en ny nøkkel for å se en igjen.",
  "Italic": "Kursiv",
  "Its API key and its models are removed. Chats stay; a chat that used one of its models switches to the default.": "API-nøkkelen og modellene dens fjernes. Chatter blir; en chat som brukte en av modellene, bytter til standard.",
  "Its key and access stay the same in every notes folder. Connect another one any time.": "Nøkkelen og tilgangen er den samme i alle notatmapper. Koble til en til når som helst.",
  "Its key is filled in on the next step": "Nøkkelen fylles inn i neste steg",
  "Its key is refused until you turn it back on. Nothing is deleted.": "Nøkkelen avvises til du slår den på igjen. Ingenting slettes.",
  "Its key is refused. Turn it on to let it connect again with the same key.": "Nøkkelen avvises. Slå den på for å la den koble til igjen med samme nøkkel.",
  "Its key stopped working. You can restore it until you reload the app.": "Nøkkelen sluttet å virke. Du kan gjenopprette den til du laster appen på nytt.",
  "Its key stops working at once. Past activity stays; you can restore it until you reload the app.": "Nøkkelen slutter å virke med én gang. Tidligere aktivitet blir; du kan gjenopprette den til du laster appen på nytt.",
  "Its key was shown only once, when it was made. A new key replaces it and the old one stops working at once.": "Nøkkelen ble bare vist én gang, da den ble laget. En ny nøkkel erstatter den, og den gamle slutter å virke med én gang.",
  "Its notes are in its folders. You can also start one here.": "Notatene ligger i mappene. Du kan også starte ett her.",
  "Its numbers, timeline and export.": "Tallene, tidslinjen og eksporten.",
  "Its old folder is not known, so it goes to the top level": "Den gamle mappen er ukjent, så den havner på øverste nivå",
  "Its page": "Siden dens",
  "Its page shows how to connect it.": "Siden dens viser hvordan den kobles til.",
  "Its page: status, recent calls, access and settings.": "Siden dens: status, siste kall, tilgang og innstillinger.",
  "Its permissions are a custom mix. Pick a level to replace them, or fine-tune them under Advanced.": "Tillatelsene er en egendefinert blanding. Velg et nivå for å erstatte dem, eller finjuster dem under Avansert.",
  "Its {n} card goes to the Archive first, where you can restore it to another lane.": "Det {n} kortet i den går først til arkivet, der du kan gjenopprette det til en annen kolonne.",
  "Its {n} cards go to the Archive first, where you can restore them to another lane.": "De {n} kortene i den går først til arkivet, der du kan gjenopprette dem til en annen kolonne.",
