  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Memora sjekker mappen og ber deg bekrefte før den bytter. Ingenting flyttes eller kopieres, og du kan bytte tilbake her. Kjører du i Docker? Bruk en mappe som er montert i containeren.",
  "Memora could not start.": "Memora kunne ikke starte.",
  "Memora data folder": "Memora-datamappe",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Memora sjekker først at den nye mappen finnes (eller kan opprettes) og at den kan lagre notater der. Mislykkes sjekken, endres ingenting.",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Memora sjekker først at den nye mappen finnes og at den kan lagre notater der. Mislykkes sjekken, endres ingenting.",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Memora på ditt språk, Mnemo som viser planen sin mens den jobber, og du som velger hva den kan bruke og se.",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Memora er en notatapp AI-appene dine også kan bruke. Du skriver i den, de leser og skriver de samme notatene, og du kan alltid se hva som er endret.",
  "Memora is free and open source": "Memora er gratis og åpen kildekode",
  "Memora is free and open source. A star helps others find it.": "Memora er gratis og åpen kildekode. En stjerne hjelper andre å finne den.",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Memora er minne, avansert: bygget for å huske det du og AI-en din lærer, og huske mer jo mer du bruker det.",
  "Memora is restarting": "Memora starter på nytt",
  "Memora is shut down": "Memora er slått av",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Memora er fortsatt tom. Koble til en AI-app, send den én prompt, så lagrer den det den vet om deg her, som notater du kan lese, redigere og se i hjernen.",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Memora har en liste over taggene dine for å foreslå dem mens du skriver. Oppdater den hvis en tagg mangler eller er utdatert.",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "Memora beholder alle versjoner av et notat når hvelvmappen er et git-repo. Kjør {cmd} i hvelvmappen én gang (se Konfigurasjon, «Versjonshistorikk» i dokumentasjonen); fra da av beholdes hver endring her.",
  "Memora keeps it in one place:": "Memora har det ett sted:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Memora lagrer hvert notat som en vanlig Markdown-fil på maskinen den kjører på. Ingenting er innelåst: åpne filene i hvilken som helst editor, ta sikkerhetskopi, eller ha dem i Git.",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Memora snakker MCP over streambar HTTP. Apper sender nøkkelen i headeren <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Memora stopper på maskinen den kjører på. Notatene dine er trygge på disken.",
  "Memora version": "Memora-versjon",
  "Memora v{latest} is available. This server runs v{current}.": "Memora v{latest} er tilgjengelig. Denne serveren kjører v{current}.",
  "Memora v{version} is available": "Memora v{version} er tilgjengelig",
  "Memora, open Overview": "Memora, åpne Oversikt",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: et notathvelv du hoster selv, med en agent som rydder i det.",
  "Memory used: {used} of {win}": "Minne brukt: {used} av {win}",
  "Mentioned in": "Nevnt i",
  "Mentions": "Omtaler",
  "Menus that fit": "Menyer som passer",
  "Menus that fit where you are, an archive you can search, softer progress and due dates, and steps you can tick on the card.": "Menyer som passer der du er, et arkiv du kan søke i, mykere fremdrift og frister, og trinn du kan krysse av på kortet.",
  "Menus, tidied": "Menyer, ryddet opp",
