  "Messaged {agent}": "Skrev til {agent}",
  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "Meldinger og meldingsfeltet står nøyaktig på linje i alle bredder, modellvelgeren har sin egen flate, den flyktige chatten passer på telefon, og valgene i et spørsmål flytter seg ikke når du trykker.",
  "Middle-drag": "Midtknapp-dra",
  "Midnight": "Midnatt",
  "Minimap": "Minikart",
  "Minimap: click or drag to move the view": "Minikart: klikk eller dra for å flytte visningen",
  "Mist": "Tåke",
  "Mnemo (AI agent)": "Mnemo (AI-agent)",
  "Mnemo and agents can do on a board everything you can, over MCP, behind four Kanban permission switches that follow Ask first, Auto and Read only.": "Mnemo og agenter kan gjøre alt du kan på en tavle, via MCP, bak fire Kanban-tillatelsesbrytere som følger Spør først, Auto og Bare lesing.",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "Mnemo-knappen er skjult. Vis den igjen fra Mer, Vis Mnemo-knappen.",
  "Mnemo goes on without sub-agents": "Mnemo fortsetter uten underagenter",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "Mnemo har ingen modell ennå: legg til en leverandør og modellene dens i Innstillinger, Mnemo",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Mnemo er innebygd i Memora. Koble til din egen AI-nøkkel, og spør med vanlige ord: den finner, skriver, tagger, lenker og rydder notater for deg.",
  "Mnemo is still answering in this chat": "Mnemo svarer fortsatt i denne chatten",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Mnemo er agenten som er innebygd i Memora. Koble til din egen AI-nøkkel og spør med vanlige ord: den holder orden på notatene dine mens de andre appene dine bruker dem.",
  "Mnemo keeps at most {n} providers; delete one first": "Mnemo beholder høyst {n} leverandører; slett én først",
  "Mnemo knows what is due": "Mnemo vet hva som forfaller",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Mnemo styrer underagentene sine, holder planen sin i chatten, og chatten passer bedre på hver skjerm.",
  "Mnemo runs its sub-agents": "Mnemo styrer underagentene sine",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Mnemo stoppet etter {n} steg; skriv «fortsett» for å gå videre.",
  "Mnemo's plan, live": "Mnemos plan, live",
  "Mnemo's question sits on its own band, its answers below as rows to tap, as many as the question needs.": "Spørsmålet fra Mnemo står på sitt eget bånd, svarene under som rader å trykke på, så mange som spørsmålet trenger.",
  "Mnemo, your notes agent": "Mnemo, notatagenten din",
