  "Not created yet · create it": "Ikke opprettet ennå · opprett den",
  "Not created yet. Click to create it.": "Ikke opprettet ennå. Klikk for å opprette den.",
  "Not done": "Ikke ferdig",
  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "Ikke gjort: Mnemo er i modusen Spør først, så endringer venter på eierens OK. Spør med ask_owner (si hva du vil endre; gi et alternativ med approve: true som «Ja, kjør på»), og gjør endringen etter at de har godkjent.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "Ikke gjort: Mnemo er i modusen Bare lesing, så notater endres ikke. Si hva du ville endret; eieren kan bytte til Spør først eller Auto i chatten.",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "Ikke gjort: chatten er i modusen Spør først, så en underagent kan ikke endre notater. Si i svaret ditt hva som bør endres; Mnemo spør eieren.",
  "Not done: the owner switched {tool} off for Mnemo (Settings, Mnemo).": "Ikke gjort: eieren har slått av {tool} for Mnemo (Innstillinger, Mnemo).",
  "Not done: the owner switched {tool} off for sub-agents (Settings, Mnemo).": "Ikke gjort: eieren har slått av {tool} for underagenter (Innstillinger, Mnemo).",
  "Not finished: the owner cut this reply before the tool returned.": "Ikke ferdig: eieren avbrøt dette svaret før verktøyet ga resultat.",
