  "Not started: \"{name}\" fits more than one model or none exactly. Close ones: {list}. Ask the owner which, or give the exact id.": "Ikke startet: «{name}» passer til mer enn én modell eller ingen nøyaktig. Nære treff: {list}. Spør eieren hvilken, eller oppgi den eksakte ID-en.",
  "Not started: there is no model \"{name}\" here. Tell the owner, or leave model out to use their default model.": "Ikke startet: det finnes ingen modell «{name}» her. Si det til eieren, eller utelat modell for å bruke standardmodellen deres.",
