  "Notes": "Notater",
  "Notes and boards share one page frame with the same spacing on phones, tablets and desktops, and the links at the foot of a note share one tidy look that folds away.": "Notater og tavler deler én sideramme med samme avstand på mobil, nettbrett og datamaskin, og lenkene nederst i et notat har ett ryddig utseende som kan felles sammen.",
  "Notes and boards, connected": "Notater og tavler, koblet sammen",
  "Notes and images in the notes folder.": "Notater og bilder i notatmappen.",
  "Notes and the links between them show up here as a map. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Notater og lenkene mellom dem vises her som et kart. Veiledningen viser hvordan du får en AI til å lagre kunnskapen sin her, eller hvordan du skriver et notat selv.",
  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "Notater vises etter hvert som AI-en lagrer dem, og lyser opp hjernen. Denne siden blir til dashbordet ditt når det første notatet kommer.",
  "Notes are not a password manager.": "Notater er ikke en passordbehandler.",
  "Notes changed in the app or in the folder": "Notater endret i appen eller i mappen",
  "Notes folder": "Notatmappe",
  "Notes folder switched": "Notatmappen er byttet",
  "Notes from {name}": "Notater fra {name}",
  "Notes in the Obsidian Kanban format open as boards. Drag cards and lanes with a mouse or a finger, and every change lands in the note’s history.": "Notater i Obsidian Kanban-formatet åpnes som tavler. Dra kort og kolonner med mus eller finger, og hver endring havner i notatets historikk.",
  "Notes in the current folder are not moved, copied or deleted. You can switch back here at any time.": "Notater i den nåværende mappen flyttes, kopieres eller slettes ikke. Du kan bytte tilbake her når som helst.",
  "Notes inside a folder": "Notater inni en mappe",
  "Notes it found": "Notater den fant",
  "Notes it saved": "Notater den lagret",
  "Notes must carry": "Notater må ha",
  "Notes tagged #{tag}": "Notater med taggen #{tag}",
  "Notes that carry at least one tag": "Notater som har minst én tagg",
  "Notes that carry every tag": "Notater som har alle taggene",
  "Notes that link nowhere and are linked from nowhere.": "Notater som ikke lenker noe sted og ikke lenkes til fra noe sted.",
  "Notes touched": "Berørte notater",
  "Notes with a tag; the start of the tag is enough": "Notater med en tagg; starten av taggen er nok",
  "Notes you delete wait here, so you can bring them back.": "Notater du sletter, venter her, så du kan hente dem tilbake.",
  "Notes you or your AIs write show up here, newest first.": "Notater du eller AI-ene dine skriver, vises her, nyeste først.",
  "Notes, folders and images in this chat": "Notater, mapper og bilder i denne chatten",
  "Nothing deleted": "Ingenting slettet",
