  "Nothing due today": "Ingenting forfaller i dag",
  "Nothing else in the last 24 hours.": "Ingenting annet de siste 24 timene.",
  "Nothing from {name} in the last 24 hours.": "Ingenting fra {name} de siste 24 timene.",
  "Nothing here": "Ingenting her",
  "Nothing hidden yet: tick the agents to hide it from. Right now all {n} agents can see it.": "Ingenting skjult ennå: huk av agentene du vil skjule det for. Akkurat nå kan alle {n} agenter se det.",
  "Nothing hidden yet: tick the agents to hide it from. Right now the only agent can see it.": "Ingenting skjult ennå: huk av agentene du vil skjule det for. Akkurat nå kan den eneste agenten se det.",
  "Nothing in 24h": "Ingenting på 24 t",
  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "Ingenting i notatnavn, mapper eller tekst, og ingenting skrevet likt. Prøv færre bokstaver, en annen stavemåte eller et ord fra inni et notat.",
  "Nothing in the last 24 hours. What your AIs do shows up here as it happens.": "Ingenting de siste 24 timene. Det AI-ene dine gjør, vises her etter hvert som det skjer.",
  "Nothing in the log goes by “{name}”. Showing all activity.": "Ingenting i loggen heter «{name}». Viser all aktivitet.",
  "Nothing in this range": "Ingenting i dette tidsrommet",
  "Nothing in your chats says “{query}”.": "Ingenting i chattene dine sier «{query}».",
  "Nothing is allowed. Turn something on, or pause the agent instead.": "Ingenting er tillatt. Slå noe på, eller sett agenten på pause i stedet.",
  "Nothing is lost: the current text stays in the history as v{n}, so you can switch back at any time.": "Ingenting går tapt: gjeldende tekst blir i historikken som v{n}, så du kan bytte tilbake når som helst.",
  "Nothing links here yet.": "Ingenting lenker hit ennå.",
