  "Notifications": "Varsler",
  "Notifications are blocked for this site. Allow them in the browser settings, then try again.": "Varsler er blokkert for dette nettstedet. Tillat dem i nettleserinnstillingene og prøv igjen.",
  "Now": "Nå",
  "Now ask {name} to save what it knows": "Be {name} lagre det den vet",
  "Nudge": "Dytt",
  "OK": "OK",
  "Ocean": "Hav",
  "Off": "Av",
  "Off for every AI.": "Av for alle AI-er.",
  "Off for every agent": "Av for alle agenter",
  "Off: its models are hidden in chats": "Av: modellene er skjult i chatter",
  "Off: tap to switch on": "Av: trykk for å slå på",
  "Offline": "Frakoblet",
  "Offline · Memora": "Frakoblet · Memora",
  "Offline, retrying": "Frakoblet, prøver igjen",
  "Older Gemini CLI without <code>gemini mcp add</code>: add the server to <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, with <code>httpUrl</code> and the same header.": "Eldre Gemini CLI uten <code>gemini mcp add</code>: legg serveren til i <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, med <code>httpUrl</code> og samme header.",
  "Older changes stay in History.": "Eldre endringer finnes i Historikk.",
  "Older messages were left out to fit the model's context.": "Eldre meldinger ble utelatt for å passe inn i modellens kontekst.",
  "Older than 30 days": "Eldre enn 30 dager",
  "Older than 7 days": "Eldre enn 7 dager",
  "Older than 90 days": "Eldre enn 90 dager",
  "Older versions of a note: read, compare, restore, and the trash.": "Eldre versjoner av et notat: les, sammenlign, gjenopprett, og papirkurven.",
  "Oldest entry": "Eldste oppføring",
  "On": "På",
  "On a board": "På en tavle",
  "On desktop, drag the edge of the chat list or the side panel to make it wider or narrower. Each keeps a minimum and remembers its width.": "På datamaskinen drar du i kanten av chatlisten eller sidepanelet for å gjøre det bredere eller smalere. Hvert har en minstebredde og husker bredden sin.",
  "On hover": "Ved peking",
  "On its avatar, its sparks in the brain and every activity row.": "På avataren, gnistene i hjernen og hver aktivitetsrad.",
  "On the Boards page each board has a ⋯ menu to open, rename, move, duplicate, colour or trash it. Right-click or a long press opens it too.": "På Tavler-siden har hver tavle en ⋯-meny for å åpne, gi nytt navn, flytte, duplisere, farge eller kaste den. Høyreklikk eller langt trykk åpner den også.",
  "On this page": "På denne siden",
  "On: tap to switch off": "På: trykk for å slå av",
  "On: {mnemo} notes what it picks up in chats. Off: only what you add here. Saved at once.": "På: {mnemo} noterer det den plukker opp i chatter. Av: bare det du legger til her. Lagres umiddelbart.",
  "Once installed, the app has its own icon, opens full screen and stays reachable when the network drops.": "Når den er installert, har appen sitt eget ikon, åpnes i fullskjerm og er tilgjengelig selv om nettverket faller ut.",
  "Once it is connected, paste this into a new chat in that app. It tells the AI to store what it knows into Memora.": "Når den er koblet til, lim dette inn i en ny chat i den appen. Det ber AI-en lagre det den vet i Memora.",
  "Once its app is set up, every call shows up here as it happens.": "Når appen er satt opp, vises hvert kall her etter hvert som det skjer.",
  "Once {name} is connected, everything it reads, writes and searches shows up here, live.": "Når {name} er koblet til, vises alt den leser, skriver og søker etter her, live.",
  "One address": "Én adresse",
  "One agent per app or device: its own key, its own name in Activity, turned off on its own.": "Én agent per app eller enhet: egen nøkkel, eget navn i Aktivitet, slås av for seg.",
  "One click": "Ett klikk",
  "One device or connection, such as 203.0.113.7. Searching \"what is my IP\" shows yours.": "Én enhet eller tilkobling, for eksempel 203.0.113.7. Søker du «what is my IP», ser du din.",
  "One device or connection.": "Én enhet eller tilkobling.",
  "One folder of notes that you and every connected AI share.": "Én mappe med notater som du og alle tilkoblede AI-er deler.",
  "One is hidden by the folder rule.": "Én er skjult av mappe-regelen.",
  "One key per agent, its own permissions.": "Én nøkkel per agent, egne tillatelser.",
  "One last step": "Ett siste steg",
  "One memory every agent reads and writes, and you can see, edit and connect all of it.": "Ett minne som hver agent leser og skriver, og som du kan se, redigere og koble sammen.",
  "One memory for every AI": "Ett minne for alle AI-er",
  "One note shows this image; it will show as missing there. The version history keeps it.": "Ett notat viser dette bildet; det vil vises som manglende der. Versjonshistorikken beholder det.",
  "One per line. They show among the suggestions on a new chat, marked Yours, and stay until you change them.": "Ett per linje. De vises blant forslagene på en ny chat, merket Dine, og blir stående til du endrer dem.",
  "One private memory that you and your AI apps share, so nothing has to be explained twice.": "Ett privat minne du og AI-appene dine deler, så ingenting må forklares to ganger.",
  "One set of notes for every AI app": "Ett sett med notater for alle AI-apper",
  "One thin progress bar instead of stark lane bars, softer shadows, lane colours across the whole lane, and overdue shown as a stroke.": "Én tynn fremdriftslinje i stedet for sterke kolonnelinjer, mykere skygger, kolonnefarger over hele kolonnen og forfalt vist som en strek.",
  "Online": "Pålogget",
  "Only PNG, JPEG, WebP and GIF images can be added": "Bare PNG-, JPEG-, WebP- og GIF-bilder kan legges til",
  "Only in the current version": "Bare i gjeldende versjon",
  "Only in version {n}": "Bare i versjon {n}",
  "Only letters, digits and - _ / . can be used.": "Bare bokstaver, tall og - _ / . kan brukes.",
  "Only looks at notes; changes nothing.": "Ser bare på notater; endrer ingenting.",
  "Only looks things up and never writes. For agents with a read-only key.": "Slår bare opp og skriver aldri. For agenter med en skrivebeskyttet nøkkel.",
  "Only pictures in your newest message go to the image model, and you hear of it in a short toast.": "Bare bilder i den nyeste meldingen din går til bildemodellen, og du får vite det i en kort melding.",
  "Only reads and answers; never changes notes": "Leser og svarer bare; endrer aldri notater",
  "Only the agents you pick. New agents can’t see it.": "Bare agentene du velger. Nye agenter kan ikke se det.",
  "Only the first rule that fits a request counts.": "Bare den første regelen som passer til en forespørsel, teller.",
  "Only the latest questions go on the page at first; earlier ones come in as you scroll up or jump to them on the timeline.": "Bare de nyeste spørsmålene kommer på siden først; eldre kommer når du ruller opp eller hopper til dem på tidslinjen.",
  "Only the ones I pick": "Bare de jeg velger",
  "Only these agents": "Bare disse agentene",
