  "Operations": "Operasjoner",
  "Optional. A few words on who you are, what you work on, how you like answers. {mnemo} keeps them and you can change them any time in Settings.": "Valgfritt. Noen få ord om hvem du er, hva du jobber med og hvordan du liker svar. {mnemo} husker dem, og du kan endre dem når som helst i Innstillinger.",
  "Or any emoji": "Eller en hvilken som helst emoji",
