  "Past due dates show in a warning tint and today’s in a softer one, and the Boards page counts what is overdue. A board’s own date colours win.": "Forfalte datoer vises i en varselfarge og dagens i en mykere, og Tavler-siden teller hva som er forfalt. Tavlens egne datofarger går foran.",
  "Paste both into the app and save.": "Lim begge inn i appen og lagre.",
  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "Lim den inn i en terminal og trykk <kbd>Enter</kbd>, og start deretter Codex i samme terminal.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "Lim den inn i en terminal og trykk <kbd>Enter</kbd>. Start deretter Claude Code, eller start den på nytt: Memora lastes av seg selv.",
