  "Paste it into the app where it asks for a key.": "Lim den inn i appen der den ber om en nøkkel.",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "Lim den inn i filen og lagre, og trykk deretter <b>Refresh</b>. Memora vises i listen.",
