  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "Lagre i Memora det jeg har delt med deg om privatlivet mitt: interessene mine, vaner, mål, menneskene som betyr noe for meg og ting jeg bryr meg om. Legg disse notatene i en mappe som heter Private, ett notat per emne, og lenk relaterte notater. Lagre aldri passord, kortnumre eller andre hemmeligheter. Når du er ferdig, fortell meg hva du lagret.",
  "Save into Memora what you know about my work: my role, my team, the projects I'm on and where they stand, and decisions we made. Make one note per project or topic and link them together.": "Lagre i Memora det du vet om jobben min: rollen min, teamet mitt, prosjektene jeg er med på og hvor de står, og beslutninger vi tok. Lag ett notat per prosjekt eller emne og lenk dem sammen.",
