  "This server is run by systemd, which starts it again a few seconds later. To keep it stopped, run {cmd} on the server instead.": "Denne serveren kjøres av systemd, som starter den igjen noen sekunder senere. For å holde den stoppet, kjør {cmd} på serveren i stedet.",
  "This server runs in Docker, which may start it again. To keep it stopped, run {cmd} on the host instead.": "Denne serveren kjører i Docker, som kan starte den igjen. For å holde den stoppet, kjør {cmd} på verten i stedet.",
