  "You now have long-term memory through Memora. Save into Memora everything you know about me from our conversations: who I am, my work, the projects I'm on, my preferences and important decisions. Make one note per topic in a fitting folder, and link notes that belong together. When you're done, tell me what you saved.": "Du har nå langtidsminne gjennom Memora. Lagre i Memora alt du vet om meg fra samtalene våre: hvem jeg er, jobben min, prosjektene jeg er med på, preferansene mine og viktige beslutninger. Lag ett notat per emne i en passende mappe, og lenk notater som hører sammen. Når du er ferdig, fortell meg hva du lagret.",
