  "{mnemo} settings saved": "{mnemo}-innstillinger lagret",
  "{mnemo} settings: models and keys": "{mnemo}-innstillinger: modeller og nøkler",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "{mnemo} starter underagenter av seg selv når en oppgave lar seg dele godt; det er ingenting å sette opp. De kjører på standardmodellen din, deretter reservemodellene, med mindre du oppgir en modell i chatten. Følg dem, og bytt modellen deres, i Agenter øverst til høyre i chatten. De bruker egne tokens, så i Spør først spør {mnemo} og sier omtrent hvor mange; i Auto bare kjører de. Lagres umiddelbart.",
