  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} kan ikke lese bilder, så den får bare navnene deres. Sett en modell som leser bilder, eller bytt modell for denne chatten.",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} kan ikke lese bilder, så den fikk bare navnene deres. Sett en modell som leser bilder, eller bytt modell for denne chatten.",
